<script lang="ts">import KanjiForm from '$lib/components/KanjiForm.svelte'; let { data, form } = $props(); function confirmDelete(e: SubmitEvent) { if (!confirm('Delete this kanji entry?')) e.preventDefault(); }</script>
<div class="page-shell form-page"><a class="back" href={`/sessions/${data.session.id}`}>Back to {data.session.title}</a><section class="panel"><p class="eyebrow">Edit character</p><h1 lang="ja">{data.entry.kanji}</h1><form method="POST" action="?/update"><KanjiForm values={form?.values ?? data.entry} errors={form?.errors} submitLabel="Save kanji" /></form><form method="POST" action="?/delete" onsubmit={confirmDelete}><input type="hidden" name="confirmation" value="delete" /><button class="danger" type="submit">Delete kanji</button></form></section></div>
